# ---------------------------------------------------------------------------
# Build output: exactly 500 unique facts, balanced across categories.
# ---------------------------------------------------------------------------

# Target per-category counts (sums to 500)
CATEGORY_LIMITS = {
    "Białko": 140,
    "Odżywianie": 180,
    "Odchudzanie": 160,
    "Trening": 140,
    "Suplementy": 120,
    "Ciało": 80,
    "Historia": 60,
    "Rekordy": 60,
    "Psychologia": 40,
    "Metabolizm": 20,
}


def clean_text(s: str) -> str:
    """Normalize text for duplicate detection."""
    return re.sub(r"[^a-ząćęłńóśźż0-9]+", "", s.lower())


def main() -> None:
    # De-duplicate within the source list (keep first occurrence).
    seen = set()
    unique_facts = []
    for fact in FACTS:
        key = clean_text(fact["text"])
        if key in seen:
            continue
        seen.add(key)
        # Also skip facts that already exist in fun-fakty.js
        if key in EXISTING_TEXTS_NORM:
            continue
        unique_facts.append(fact)

    # Balance per category down to the target limit.
    counts: dict[str, int] = {}
    balanced = []
    for fact in unique_facts:
        tag = fact["tag"]
        counts[tag] = counts.get(tag, 0)
        if counts[tag] < CATEGORY_LIMITS.get(tag, 0):
            balanced.append(fact)
            counts[tag] += 1

    total = len(balanced)
    print(f"Generated {total} fun facts.")
    if total != 1000:
        print("WARNING: expected 1000, got", total)

    out = Path(__file__).resolve().parent.parent / "fun-facts-new.json"
    out.write_text(json.dumps(balanced, ensure_ascii=False, indent=2), encoding="utf-8")
    print(f"Wrote {out}")


# Normalized set of existing texts from fun-fakty.js
EXISTING_TEXTS_NORM = {clean_text(t) for t in EXISTING_TEXTS}

if __name__ == "__main__":
    main()
